<?php
/** Deterministic no-cost functional coverage for 1.4.1 Clear Chat. */

class ACL_AR_ClearFakeSwitchboard implements \ACL\AgentRooms\Contracts\SwitchboardClientInterface {
	public int $calls = 0;
	public array $requests = array();
	public $during_send = null;
	public bool $brain = false;
	public function send( array $request ) {
		$this->calls++; $this->requests[] = $request;
		if ( is_callable( $this->during_send ) ) { ( $this->during_send )(); $this->during_send = null; }
		if ( $this->brain ) {
			$rows=array();foreach((array)($request['metadata']['agent_ids']??array())as$id){$rows[]=array('agent_id'=>(int)$id,'content'=>'POST CLEAR BRAIN '.(int)$id);}
			return array('content'=>wp_json_encode(array('responses'=>$rows)),'usage'=>array('prompt_tokens'=>11,'completion_tokens'=>7,'total_tokens'=>18),'estimated_cost'=>0);
		}
		return array('content'=>'POST CLEAR INDEPENDENT','usage'=>array('prompt_tokens'=>9,'completion_tokens'=>4,'total_tokens'=>13),'estimated_cost'=>0);
	}
}

class ACL_AR_ClearRecoveryMessageRepository extends \ACL\AgentRooms\Repositories\MessageRepository {
	public $after_find = null;
	public function find_by_response_job_id( int $job_id ): ?array {
		$response = parent::find_by_response_job_id( $job_id );
		if ( $response && is_callable( $this->after_find ) ) {
			$callback         = $this->after_find;
			$this->after_find = null;
			$callback( $response );
		}
		return $response;
	}
}

