		$trigger=$this->legacy('NEW BRAIN',$this->owner);$run=$runs->create($this->room,$this->brain,(int)$trigger['id'],array($this->brain_agent),'controlled-fake','brain-model');$ok_brain=new ACL_AR_ClearFakeSwitchboard();$ok_brain->brain=true;$done=(new \ACL\AgentRooms\Services\BrainRuntime($runs,null,$this->rooms,$agents,$this->events,$this->messages,null,null,$ok_brain))->run((int)$run['id']);$this->assert_same('completed',$done['status'],'New post-clear Brain run failed.');$this->assert_same(1,$ok_brain->calls,'New Brain run call count.');$this->assert_same(1,(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}acl_ar_messages WHERE brain_run_id=%d",(int)$run['id'])),'New Brain response missing.');
	}

	private function rest_health_and_source():void{
		global$wpdb;$controller=new \ACL\AgentRooms\Rest\RoomClearController($this->rooms,new \ACL\AgentRooms\Services\AccessService($this->rooms));add_action('rest_api_init',array($controller,'register_routes'));do_action('rest_api_init');remove_action('rest_api_init',array($controller,'register_routes'));$routes=rest_get_server()->get_routes();$route='/acl-agent-rooms/v1/rooms/(?P<room_id>[\d]+)/clear';$this->assert_true(isset($routes[$route]),'Clear REST route missing.');$methods=$routes[$route][0]['methods'];$this->assert_true('POST'===$methods||(is_array($methods)&&!empty($methods['POST'])),'Clear REST method.');$request=new \WP_REST_Request('POST','/');$request->set_param('room_id',$this->room);$request->set_param('confirm',true);$request->set_param('idempotency_key',$this->prefix.'-rest-key');$this->assert_wp_error($controller->permissions($request),'Missing nonce accepted.');$request->set_header('X-WP-Nonce',wp_create_nonce('wp_rest'));wp_set_current_user($this->member);$this->assert_wp_error($controller->permissions($request),'Ordinary member REST clear accepted.');wp_set_current_user(0);$this->assert_wp_error($controller->permissions($request),'Unauthenticated REST clear accepted.');wp_set_current_user($this->owner);$bad=new \WP_REST_Request('POST','/');$bad->set_param('room_id',$this->room);$bad->set_header('X-WP-Nonce','invalid');$this->assert_wp_error($controller->permissions($bad),'Invalid nonce accepted.');
		$endpoint_source=file_get_contents(dirname(__DIR__).'/includes/Rest/RoomClearController.php');foreach(array("'confirm'","'idempotency_key'",'private, no-store','can_clear_room','verify_nonce')as$n){$this->assert_true(false!==strpos($endpoint_source,$n),'REST contract missing '.$n);}$api=file_get_contents(dirname(__DIR__).'/assets/js/room/api.js');$this->assert_true(false!==strpos($api,"Api.prototype.clearRoom"),'Client clear route missing.');$this->assert_true(false!==strpos($api,"buildRestUrl"),'Central REST URL composer missing.');
		$admin=file_get_contents(dirname(__DIR__).'/includes/Admin/RoomsPage.php');$this->assert_true(false!==strpos($admin,'Enable Clear Chat'),'Admin setting label missing.');$this->assert_true(false!==strpos($admin,'Earlier records remain preserved for audit and retention'),'Admin help text missing.');$shortcode=file_get_contents(dirname(__DIR__).'/includes/Shortcodes/AgentRoomShortcode.php');$this->assert_true(false!==strpos($shortcode,'canClearChat'),'Manager-only bootstrap permission missing.');$clear_js=file_get_contents(dirname(__DIR__).'/assets/js/room/clear-chat.js');$this->assert_true(false===strpos($clear_js,'window.confirm'),'Browser confirm was used.');$this->assert_true(false!==strpos($clear_js,'This will clear the visible transcript for everyone in this room.'),'Confirmation copy missing.');
		$health=(new \ACL\AgentRooms\Services\HealthService())->snapshot();$this->assert_true(isset($health['clear_chat']['invalid_cutoff_references'],$health['clear_chat']['impossible_cutoffs'],$health['clear_chat']['missing_actor_references'],$health['clear_chat']['failed_operations'],$health['clear_chat']['duplicate_retries']),'Clear health checks missing.');$saved=$this->rooms->find($this->disabled_room);$wpdb->update($wpdb->prefix.'acl_ar_rooms',array('cleared_through_event_id'=>PHP_INT_MAX),array('id'=>$this->disabled_room));$broken=(new \ACL\AgentRooms\Services\HealthService())->snapshot();$this->assert_true($broken['clear_chat']['impossible_cutoffs']>=1,'Impossible cutoff not detected.');$wpdb->update($wpdb->prefix.'acl_ar_rooms',array('cleared_through_event_id'=>$saved['cleared_through_event_id']),array('id'=>$this->disabled_room));
		$this->assert_true(false!==strpos(file_get_contents(dirname(__DIR__).'/includes/Services/RoomClearService.php'),'START TRANSACTION'),'Clear transaction missing.');$this->assert_true(false!==strpos(file_get_contents(dirname(__DIR__).'/includes/Repositories/JobRepository.php'),'chat_cleared'),'Independent cancel policy missing.');$this->assert_true(false!==strpos(file_get_contents(dirname(__DIR__).'/includes/Repositories/BrainRunRepository.php'),'chat_cleared'),'Brain cancel policy missing.');$this->assert_true(false!==strpos(file_get_contents(dirname(__DIR__).'/includes/Services/BrainRuntime.php'),'trigger_cleared'),'Brain discard policy missing.');$this->assert_true(false!==strpos(file_get_contents(dirname(__DIR__).'/includes/Services/AgentRuntime.php'),'trigger_cleared'),'Independent discard policy missing.');
	}

	private function legacy(string$content,int$user):array{$id=$this->messages->create(array('room_id'=>$this->room,'sender_type'=>'user','sender_user_id'=>$user,'content'=>$content,'client_request_id'=>$this->prefix.'-'.wp_generate_password(12,false,false)));$event=$this->writer->create_message_event($this->messages->find((int)$id));return $event;}
	private function fingerprint():string{global$wpdb;$like=$wpdb->esc_like($wpdb->prefix.'acl_ar_').'%';$c=$wpdb->get_results($wpdb->prepare('SELECT TABLE_NAME,COLUMN_NAME,ORDINAL_POSITION,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT,EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=%s AND TABLE_NAME LIKE %s ORDER BY TABLE_NAME,ORDINAL_POSITION',DB_NAME,$like),ARRAY_A);$i=$wpdb->get_results($wpdb->prepare('SELECT TABLE_NAME,INDEX_NAME,NON_UNIQUE,SEQ_IN_INDEX,COLUMN_NAME,SUB_PART,INDEX_TYPE FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=%s AND TABLE_NAME LIKE %s ORDER BY TABLE_NAME,INDEX_NAME,SEQ_IN_INDEX',DB_NAME,$like),ARRAY_A);return hash('sha256',wp_json_encode(array($c,$i)));}
	private function cleanup():void{global$wpdb;wp_set_current_user($this->owner);foreach(array($this->room,$this->disabled_room)as$room){if(!$room){continue;}$wpdb->delete($wpdb->prefix.'acl_ar_usage',array('room_id'=>$room),array('%d'));if($this->rooms&&$this->rooms->find($room)){$this->rooms->delete($room);}}$agents=new \ACL\AgentRooms\Repositories\AgentRepository();foreach(array($this->agent,$this->brain_agent)as$id){if($id&&$agents->find($id)){$agents->delete($id);}}if($this->brain){(new \ACL\AgentRooms\Repositories\BrainRepository())->delete($this->brain);}if($this->member){wp_delete_user($this->member);}if($this->owner){wp_delete_user($this->owner);}if(null===$this->clear_health_before){delete_option('acl_ar_clear_health');}else{update_option('acl_ar_clear_health',$this->clear_health_before,false);}}
